$ErrorActionPreference = "Stop"

$ProjectRoot = "C:\Projects\SmartTimetable"
$FrontendRoot = Join-Path $ProjectRoot "frontend"
$Target = Join-Path $FrontendRoot "src\pages\Timetable.tsx"
$BackupDir = Join-Path $FrontendRoot "audit_backups"

if (-not (Test-Path -LiteralPath $Target)) {
    throw "Target Timetable.tsx not found: $Target"
}

New-Item -ItemType Directory -Force -Path $BackupDir | Out-Null

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $BackupDir "Timetable.tsx_before_teacher_code_fix_$stamp.tsx"
Copy-Item -LiteralPath $Target -Destination $backup -Force

