    Write-Host "  GEO/HIST/GOV/CS  -> corresponding teacher numbers"
    Write-Host "  BUS/AGRI         -> corresponding teacher numbers"
    Write-Host ""
    Write-Host "Teacher number source order:"
    Write-Host "  teacher_code / employee_code, then teacher_number."
    Write-Host "Teacher numbers such as T019 / EMP019 are displayed as 19."
    Write-Host ""
} catch {
    Write-Host ""
    Write-Host "BUILD FAILED. Restoring previous Timetable.tsx..."
    Copy-Item -LiteralPath $backup -Destination $Target -Force
    Write-Host "Original file restored."
    exit 1
}
